import base64,gzip,hashlib,json,xml.etree.ElementTree as ET
from pathlib import Path
C=Path(__file__).parent;sha=lambda b:hashlib.sha256(b).hexdigest();z=(C/'signature-reference-results.json.gz').read_bytes();assert sha(z)=='3c23a1cce5e66074417dc8261758f8906e1fbe091838d27ff325a8570f85ab4e';assert gzip.decompress(z)==(C/'signature-reference-results.json').read_bytes();v=json.loads(gzip.decompress(z));m=json.loads((C/'signature-reference-manifest.json').read_text());e=v['environment'];assert len(v['results'])==len(m['cases'])==4;assert e['manifest_sha256']==sha((C/'signature-reference-manifest.json').read_bytes());assert e['headless'] and e['jar_sha256']=='aa5262a23e7f1fa50bdf9f6492e8d9f8683b2f18e2f182776966e17bdb282053';assert sha((C/'signature-reference-transport.json').read_bytes())=='b123ccbf445c20c1e0a626b37580e83a3052c0e16715addf5985b4db3221c228';assert base64.b64decode(json.loads((C/'signature-reference-transport.json').read_text())['data'])==z
rows=[];classification=[]
for req,r in zip(m['cases'],v['results']):
 s=Path(req['source']);b=s.read_bytes();assert req['name']==r['name'];assert sha(b)==req['source_sha256']==r['source_sha256']==r['stdin_sha256'];assert len(b)==r['source_bytes']==r['stdin_bytes'];assert r['cwd']==e['worker']+'/new';assert r['actual_wrapper_argv']==[r['cwd'] if x=='PRIVATE_CWD' else x for x in req['invocation']];assert r['actual_java_argv']==[e['java'],'-Djava.awt.headless=true','-Dfile.encoding=UTF-8','-Duser.language=en','-Duser.country=AU','-Duser.timezone=GMT+11:00','-jar',e['jar'],'-pipe','-tsvg'];assert r['timezone']=='GMT+11:00' and not r['timed_out'];assert e['env_overrides']=={}
 for key,suffix in [('stdout','.svg'),('stderr','.stderr')]:
  data=base64.b64decode(r[key+'_base64'],validate=True);assert sha(data)==r[key+'_sha256'];s.with_suffix(suffix).write_bytes(data)
 root=ET.parse(s.with_suffix('.svg')).getroot();valid=r['exit_code']==0 and root.attrib.get('data-diagram-type')=='SEQUENCE' and not s.with_suffix('.stderr').read_bytes();classification.append(dict(name=r['name'],java_exit=r['exit_code'],xml_valid=True,diagram_type=root.attrib.get('data-diagram-type'),intended_valid=req['intended_valid'],observed_valid=valid,error_marker=('Syntax Error' in s.with_suffix('.svg').read_text() or 'An error has occured' in s.with_suffix('.svg').read_text() or 'Use' in s.with_suffix('.svg').read_text() and 'accross' in s.with_suffix('.svg').read_text()),source_sha256=sha(b),stdout_sha256=r['stdout_sha256'],stderr_sha256=r['stderr_sha256']))
 rows.append(dict(source=str(s),golden=str(s.with_suffix('.svg')),cohort='signature4',axes=req['axes']))
(C/'signature-reference-classification.json').write_text(json.dumps(classification,indent=2)+'\n');(C/'signature4.json').write_text(json.dumps(rows,indent=2)+'\n');print('valid',sum(x['observed_valid'] for x in classification),'invalid',sum(not x['observed_valid'] for x in classification))
